const { default: BigNumber } = require('bignumber.js');
const superagent = require('superagent');
const utils = require('../utils');
const ABI = require('./abi.json');

const CIV_TOKEN = '0x37fE0f067FA808fFBDd12891C0858532CFE7361d';
const MASTERCHEF_ADDRESS = '0x8a774F790aBEAEF97b118112c790D0dcccA61099';
const POOLS_ONE_TOKEN = [
  '0x73a83269b9bbafc427e76be0a2c1a1db2a26f4c2',
  '0x37fe0f067fa808ffbdd12891c0858532cfe7361d'
];
const API_POOL_DATA = (poolId) => `https://api.civfund.org/getPoolData/${poolId}/?chainId=1`;

const getApy = async () => {
  const poolLength = await sdk.api.abi.call({
    target: MASTERCHEF_ADDRESS,
    chain: 'ethereum',
    abi: ABI.poolLength,
  });

  const poolRes = await Promise.all([...Array(Number(poolLength.output)).keys()].map((i) => utils.getData(API_POOL_DATA(i))));
  const [underlyingToken0, underlyingToken1] = await Promise.all(
    ['token0', 'token1'].map((method) =>
      sdk.api.abi.multiCall({
        abi: ABI[method],
        calls: poolRes.filter(e => !POOLS_ONE_TOKEN.includes(e.lpToken)).map(({lpToken}) => ({
          target: lpToken,
        })),
        chain: 'ethereum',
        requery: true,
      })
    )
  );
  let tokens0 = underlyingToken0.output.map((res) => res.output);
  let tokens1 = underlyingToken1.output.map((res) => res.output);

  tokens0 = [
    ...POOLS_ONE_TOKEN,
    ...tokens0,
  ];
  tokens1 = [undefined, undefined, ...tokens0];

  const poolApy = poolRes.map((pool, i) => {
    const apy = pool.roiPerYearPerc;
    return {
      pool: `ethereum:${pool.lpToken}`,
      chain: utils.formatChain('ethereum'),
      project: 'civfund',
      symbol: `${pool.symbol1}${pool.symbol2 ? '-' + pool.symbol2 : ''}`,
      tvlUsd: Number(pool.tvlUSD),
      apy,
      underlyingTokens: !pool.symbol2 ? [pool.lpToken]  : [tokens0[i], tokens1[i]],
      rewardTokens: ['0x73a83269b9bbafc427e76be0a2c1a1db2a26f4c2'] // ONE
    }
  });

  return poolApy;
};

module.exports = {
  timetravel: false,
  apy: getApy,
  url: 'https://civfund.org/',
};

const { request, gql } = require('graphql-request');
const sdk = require('@defillama/sdk');
const superagent = require('superagent');
const { default: BigNumber } = require('bignumber.js');
const {
  utils: { formatEther },
} = require('ethers');
const abi = require('./abi');

const GRAPH_URL =
  'https://api.thegraph.com/subgraphs/name/rocifi/rocifi-matic-lending-v2';

const chain = 'polygon';

const ONE_HOUR = 3600;
const ONE_DAY = ONE_HOUR * 24;
const ONE_WEEK = ONE_DAY * 7;
const ONE_YEAR = ONE_HOUR * 8760;

const ROCI_SETTINGS_PROVIDER = '0xb2e577a112A6F2C6d3d511ade2AD512cEA312a6d';
const ROCI_LIMIT_MANAGER = '0x347892c2c0C230f0803127F4E1137b3e975F57E4';

const getDtPricesQuery = (pool) => gql`
  query RociFiDtPrices {
    dtPriceUpdates(
      orderBy: "timestamp"
      orderDirection: "desc"
      first: 10
      where: {
        market: "${pool.toLowerCase()}",
        timestamp_gte: ${Math.floor(Date.now() / 1000) - ONE_WEEK}
      }
    ) {
      dtPrice
      timestamp
    }
  }
`;

const getApy = async (pool) => {
  const graphData = await request(GRAPH_URL, getDtPricesQuery(pool));
  if (
    !graphData?.dtPriceUpdates?.length ||
    graphData.dtPriceUpdates.length === 1
  )
    return 0;

  const { dtPriceUpdates } = graphData;

  const priceUpdateA = dtPriceUpdates[0];

  const priceUpdateB =
    dtPriceUpdates.find(
      (p) => priceUpdateA.timestamp - p.timestamp >= ONE_DAY
    ) || dtPriceUpdates[dtPriceUpdates.length - 1];

  const timestampDiff =
    Number(priceUpdateA.timestamp) - Number(priceUpdateB.timestamp);

  const apy = BigNumber(priceUpdateA.dtPrice)
    .minus(priceUpdateB.dtPrice)
    .dividedBy(priceUpdateB.dtPrice)
    .multipliedBy(ONE_YEAR)
    .dividedBy(timestampDiff)
    .multipliedBy(100)
    .toNumber();

  return apy;
};

const getPricesByAddresses = async (addresses) => {
  const prices = (
    await superagent.post('https://coins.llama.fi/prices').send({
      coins: addresses.map((address) => `${chain}:${address}`),
    })
  ).body.coins;

  return Object.entries(prices).reduce(
    (acc, [name, price]) => ({
      ...acc,
      [name.split(':')[1]]: price.price,
    }),
    {}
  );
};

async function getPools() {
  const pools = (
    await sdk.api.abi.call({
      target: ROCI_SETTINGS_PROVIDER,
      abi: abi.settingsProvider.getPools,
      chain,
    })
  ).output;

  return Promise.all(
    await pools.map(async (pool) => {
      const [symbol, underlyingToken] = await Promise.all(
        ['symbol', 'underlyingToken'].map(async (method) => {
          const response = await sdk.api.abi.call({
            target: pool,
            chain,
            abi: abi.pool[method],
          });

          return response.output;
        })
      );

      const [underlyingDecimals, underlyingSymbol, poolTvl] = await Promise.all(
        ['decimals', 'symbol', 'balanceOf'].map(async (method) => {
          const response = await sdk.api.abi.call({
            target: underlyingToken,
            abi: `erc20:${method}`,
            chain,
            params: method === 'balanceOf' ? [pool] : undefined,
          });
          return response.output;
        })
      );

      const totalBorrowed = (
        await sdk.api.abi.call({
          target: ROCI_LIMIT_MANAGER,
          chain,
          abi: abi.limitManager.poolToBorrowedAmount,
          params: [pool],
        })
      ).output;

      const scoreTenLTVs = (
        await sdk.api.abi.call({
          target: ROCI_SETTINGS_PROVIDER,
          chain,
          abi: abi.settingsProvider.getPoolToScoreLtvs,
          params: [pool, 10],
        })
      ).output;

      const ltv =
        parseFloat(formatEther(scoreTenLTVs[scoreTenLTVs.length - 1])) / 100;

      const scoreTenBorrowSettings = (
        await sdk.api.abi.call({
          target: ROCI_SETTINGS_PROVIDER,
          chain,
          abi: abi.settingsProvider.getInterestSettings,
          params: [pool, 10, scoreTenLTVs[0], 7 * ONE_DAY],
        })
      ).output;

      const apyBaseBorrow = parseFloat(
        formatEther(scoreTenBorrowSettings.interest)
      );

      return {
        address: pool,
        symbol,
        underlyingToken: underlyingToken?.toLowerCase(),
        underlyingDecimals,
        underlyingSymbol,
        tvl: poolTvl,
        totalBorrowed,
        apyBaseBorrow,
        ltv,
      };
    })
  );
}

async function getPoolData() {
  const pools = await getPools();
  const prices = await getPricesByAddresses(
    pools.map((pool) => pool.underlyingToken)
  );

  return Promise.all(
    pools.map(async (pool, index) => {
      const price = prices[pool.underlyingToken];

      const decimals = Number(pool.underlyingDecimals);

      const totalSupply = BigNumber(pool.tvl).plus(pool.totalBorrowed);

      const [tvlUsd, totalSupplyUsd, totalBorrowUsd] = [
        pool.tvl,
        totalSupply,
        pool.totalBorrowed,
      ].map((value) =>
        BigNumber(value).shiftedBy(-decimals).multipliedBy(price).toNumber()
      );

      const apyBase = await getApy(pool.address);

      return {
        pool: `${pool.address}-${chain}`,
        chain,
        project: 'rocifi-v2',
        symbol: pool.symbol,
        tvlUsd,
        apyBase,
        underlyingTokens: [pool.underlyingToken],
        poolMeta: `RociFi ${pool.underlyingSymbol} lending pool`,
        totalBorrowUsd,
        totalSupplyUsd,
        apyBaseBorrow: pool.apyBaseBorrow,
        ltv: pool.ltv,
      };
    })
  );
}

module.exports = {
  timetravel: false,
  apy: getPoolData,
  url: 'https://roci.fi/app/markets',
};

const axios = require('axios');

const apiUrl_avax = 'https://data.cian.app/api/v1/staking_avax/apr';
const apiUrl_btc = 'https://data.cian.app/api/v1/staking_btc/apr';
const apiUrl_maticx = 'https://data.cian.app/polygon/api/v1/staking_matic/apy';
const apiUrl_stmatic = 'https://data.cian.app/polygon/api/v1/staking_stmatic/apy';
const apiUrl_steth = 'https://data.cian.app/ethereum/api/v1/staking_eth/apy';

async function fetch() {
  const response_avax = (await axios.get(apiUrl_avax)).data.data;
  const response_btc = (await axios.get(apiUrl_btc)).data.data;
  const response_maticx = (await axios.get(apiUrl_maticx)).data.data;
  const response_stmatic = (await axios.get(apiUrl_stmatic)).data.data;
  const response_steth = (await axios.get(apiUrl_steth)).data.data;
  return [...response_avax, ...response_btc, ...response_maticx, ...response_stmatic,response_steth];
}

const main = async () => {
  const data = await fetch();

  return data.map((p) => {
    // if - in symbol -> split, keep 1 in array, otherwise don't split
    let symbolSplit = p.symbol.split('-');
    symbolSplit = symbolSplit.length > 1 ? symbolSplit[1] : symbolSplit[0];
    const symbol = symbolSplit.replace(/ *\([^)]*\) */g, '');
    // extract content within () -> meta data
    const poolMeta = /\(([^)]+)\)/.exec(symbolSplit)[1];

    return {
      ...p,
      symbol,
      poolMeta,
    };
  });
};

module.exports = {
  timetravel: false,
  apy: main,
  url: 'https://dapp.cian.app',
};

